from __future__ import annotations
import ast, json, py_compile, shutil, sys, tempfile
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
TAG = "streamerbot_attention_stack_v1_" + datetime.now().strftime("%Y%m%d_%H%M%S")

ATTENTION_LAYER = '\nfrom __future__ import annotations\nimport json, re, sqlite3, time, uuid\nfrom dataclasses import dataclass, asdict\nfrom pathlib import Path\nfrom typing import Any\n\nROOT = Path(__file__).resolve().parent\nLOGS = ROOT / "Logs"\n\ndef resolve_db_path(db_path=None) -> Path:\n    if db_path:\n        return Path(db_path)\n    try:\n        import config  # type: ignore\n        for name in ("KNOWLEDGE_DB_PATH", "DB_PATH", "DATABASE_PATH"):\n            value = getattr(config, name, None)\n            if value:\n                return Path(value)\n    except Exception:\n        pass\n    return ROOT / "knowledge.db"\n\ndef now_ts() -> float:\n    return time.time()\n\ndef iso_now() -> str:\n    import datetime as _dt\n    return _dt.datetime.fromtimestamp(time.time()).strftime("%Y-%m-%d %H:%M:%S")\n\ndef normalize_text(text: str) -> str:\n    return re.sub(r"\\s+", " ", str(text or "").replace("\\u00a0", " ")).strip()\n\ndef text_lc(text: str) -> str:\n    return normalize_text(text).casefold()\n\ndef stable_id(prefix: str) -> str:\n    return f"{prefix}_{uuid.uuid4().hex[:16]}"\n\ndef token_count(text: str) -> int:\n    return len(re.findall(r"[\\wА-Яа-яЁё]+", text, flags=re.UNICODE))\n\n@dataclass\nclass AttentionDecision:\n    event_id: str\n    source: str\n    event_type: str\n    user_id: str\n    user_name: str\n    text: str\n    score: float\n    bucket: str\n    action: str\n    reasons: list[str]\n    priority: int\n    created_ts: float\n    def to_dict(self) -> dict[str, Any]:\n        return asdict(self)\n\nclass AttentionLayer:\n    def __init__(self, db_path=None):\n        self.db_path = resolve_db_path(db_path)\n        LOGS.mkdir(parents=True, exist_ok=True)\n        self.init_schema()\n\n    def connect(self):\n        conn = sqlite3.connect(str(self.db_path))\n        conn.row_factory = sqlite3.Row\n        return conn\n\n    def init_schema(self):\n        with self.connect() as conn:\n            conn.execute("""\n            CREATE TABLE IF NOT EXISTS attention_events(\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                event_id TEXT UNIQUE,\n                source TEXT, event_type TEXT,\n                user_id TEXT, user_name TEXT, text TEXT,\n                raw_json TEXT,\n                score REAL, bucket TEXT, action TEXT, reasons_json TEXT,\n                priority INTEGER, selected INTEGER DEFAULT 0, consumed INTEGER DEFAULT 0,\n                created_ts REAL, created_at TEXT\n            )""")\n            conn.execute("""\n            CREATE TABLE IF NOT EXISTS attention_selected(\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                event_id TEXT UNIQUE,\n                source TEXT, event_type TEXT,\n                user_id TEXT, user_name TEXT, text TEXT,\n                score REAL, action TEXT, reasons_json TEXT,\n                priority INTEGER, consumed INTEGER DEFAULT 0,\n                created_ts REAL, created_at TEXT\n            )""")\n            conn.execute("""\n            CREATE TABLE IF NOT EXISTS attention_viewer_state(\n                user_id TEXT PRIMARY KEY,\n                user_name TEXT, message_count INTEGER DEFAULT 0,\n                last_text TEXT, last_text_count INTEGER DEFAULT 0,\n                last_seen_ts REAL, last_seen_at TEXT\n            )""")\n            conn.execute("""\n            CREATE TABLE IF NOT EXISTS attention_digest_log(\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                digest TEXT, event_count INTEGER,\n                created_ts REAL, created_at TEXT\n            )""")\n            conn.commit()\n\n    def _repeat_info(self, conn, user_id: str, user_name: str, text: str) -> tuple[int, int]:\n        if not user_id:\n            return 0, 0\n        norm = text_lc(text)\n        row = conn.execute("SELECT message_count,last_text,last_text_count FROM attention_viewer_state WHERE user_id=?", (user_id,)).fetchone()\n        if row is None:\n            conn.execute("""INSERT INTO attention_viewer_state(user_id,user_name,message_count,last_text,last_text_count,last_seen_ts,last_seen_at)\n                            VALUES(?,?,?,?,?,?,?)""", (user_id, user_name, 1, norm, 1, now_ts(), iso_now()))\n            return 1, 1\n        message_count = int(row["message_count"] or 0) + 1\n        repeat = int(row["last_text_count"] or 0) + 1 if str(row["last_text"] or "") == norm and norm else 1\n        conn.execute("""UPDATE attention_viewer_state\n                        SET user_name=?, message_count=?, last_text=?, last_text_count=?, last_seen_ts=?, last_seen_at=?\n                        WHERE user_id=?""",\n                     (user_name, message_count, norm, repeat, now_ts(), iso_now(), user_id))\n        return message_count, repeat\n\n    def score_creator_event(self, text: str, event_type="voice") -> AttentionDecision:\n        return AttentionDecision(stable_id("creator"), "creator_voice", event_type, "Duncan", "Duncan",\n                                 normalize_text(text), 1.0, "critical", "ANSWER_CREATOR", ["creator"], 100, now_ts())\n\n    def score_vision_event(self, data: dict[str, Any]) -> AttentionDecision:\n        typ = str(data.get("event_type") or data.get("type") or "vision")\n        text = normalize_text(data.get("text") or data.get("summary") or data.get("sceneName") or data.get("obs.sceneName") or "")\n        reasons = ["vision_or_obs"]\n        score, priority, action = 0.45, 45, "REMEMBER_CONTEXT"\n        lc = text_lc(text)\n        if typ in {"SceneChanged","StreamingStarted","StreamingStopped","RecordingStarted","RecordingStopped"}:\n            score += 0.15; priority += 15; reasons.append("obs_state_change")\n        if any(x in lc for x in ("dark souls","elden ring","босс","смерть","костёр","hp","игра")):\n            score += 0.18; priority += 10; reasons.append("game_or_scene_signal")\n        bucket = "selected" if score >= 0.7 else "background"\n        if bucket == "selected":\n            action = "COMMENT_SCREEN"\n        return AttentionDecision(stable_id("vision"), str(data.get("source") or "vision_context"), typ, "", "",\n                                 text, round(min(score,1.0),3), bucket, action, reasons, min(priority,90), now_ts())\n\n    def score_twitch_message(self, data: dict[str, Any], conn=None) -> AttentionDecision:\n        text = normalize_text(data.get("message") or data.get("text") or data.get("rawInput") or data.get("input") or "")\n        user_name = str(data.get("displayName") or data.get("user_name") or data.get("userName") or data.get("username") or data.get("login") or "")\n        user_id = str(data.get("user_id") or data.get("userId") or data.get("id") or user_name or "")\n        lc = text_lc(text)\n        reasons: list[str] = []\n        score, priority = 0.18, 25\n        repeat = 0\n        if conn is not None:\n            _, repeat = self._repeat_info(conn, user_id, user_name, text)\n        if not text:\n            score -= 1; reasons.append("empty")\n        if len(text) > 400:\n            score -= .35; reasons.append("too_long")\n        if token_count(text) <= 1 and not any(x in lc for x in ("мони","monika","?")):\n            score -= .25; reasons.append("too_short")\n        if repeat >= 3:\n            score -= .65; reasons.append("repeat_spam")\n        if re.search(r"(.)\\1{8,}", text):\n            score -= .25; reasons.append("char_spam")\n        if any(x in lc for x in ("моника","моник","monika","@monika","мона")):\n            score += .45; priority += 25; reasons.append("mentions_monika")\n        if "?" in text or re.search(r"\\b(как|что|почему|зачем|когда|где|кто|можешь|скажешь|думаешь)\\b", lc):\n            score += .25; priority += 10; reasons.append("question")\n        if any(x in lc for x in ("звук пропал","нет звука","не слышно","лагает","стрим упал","экран чёрный","черный экран")):\n            score += .55; priority += 40; reasons.append("stream_health")\n        badges = text_lc(str(data.get("badges") or ""))\n        if "broadcaster" in badges:\n            score += .65; priority += 40; reasons.append("broadcaster")\n        elif "moderator" in badges:\n            score += .22; priority += 12; reasons.append("moderator")\n        elif "vip" in badges:\n            score += .18; priority += 10; reasons.append("vip")\n        elif "subscriber" in badges:\n            score += .12; priority += 8; reasons.append("subscriber")\n        if "http://" in lc or "https://" in lc:\n            score -= .2; reasons.append("link")\n        score = round(max(0.0, min(score, 1.0)), 3)\n        if score >= .85:\n            bucket, action = "critical", "ANSWER_VIEWER"\n        elif score >= .62:\n            bucket, action = "selected", "ANSWER_VIEWER"\n        elif score >= .38:\n            bucket, action = "background", "REMEMBER_CONTEXT"\n        else:\n            bucket, action = "ignored", "IGNORE"\n        if "stream_health" in reasons:\n            action = "ALERT_CREATOR"\n        return AttentionDecision(str(data.get("messageId") or data.get("event_id") or stable_id("tw")),\n                                 "twitch_chat", "ChatMessage", user_id, user_name, text, score, bucket,\n                                 action, reasons, max(0,min(priority,100)), now_ts())\n\n    def enqueue_decision(self, d: AttentionDecision, raw: dict[str, Any] | None = None) -> AttentionDecision:\n        reasons_json = json.dumps(d.reasons, ensure_ascii=False)\n        raw_json = json.dumps(raw or {}, ensure_ascii=False)\n        selected = 1 if d.bucket in ("selected","critical") else 0\n        with self.connect() as conn:\n            conn.execute("""INSERT OR IGNORE INTO attention_events(\n                event_id,source,event_type,user_id,user_name,text,raw_json,score,bucket,action,reasons_json,priority,selected,consumed,created_ts,created_at)\n                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,0,?,?)""",\n                (d.event_id,d.source,d.event_type,d.user_id,d.user_name,d.text,raw_json,d.score,d.bucket,d.action,reasons_json,d.priority,selected,d.created_ts,iso_now()))\n            if selected:\n                conn.execute("""INSERT OR IGNORE INTO attention_selected(\n                    event_id,source,event_type,user_id,user_name,text,score,action,reasons_json,priority,consumed,created_ts,created_at)\n                    VALUES(?,?,?,?,?,?,?,?,?,?,0,?,?)""",\n                    (d.event_id,d.source,d.event_type,d.user_id,d.user_name,d.text,d.score,d.action,reasons_json,d.priority,d.created_ts,iso_now()))\n            conn.commit()\n        self._jsonl(LOGS / "attention_events.jsonl", {"decision": d.to_dict(), "raw": raw or {}})\n        if selected:\n            self._jsonl(LOGS / "monika_selected_events.jsonl", d.to_dict())\n        return d\n\n    def enqueue_twitch_message(self, data: dict[str, Any], raw: dict[str, Any] | None = None) -> AttentionDecision:\n        with self.connect() as conn:\n            d = self.score_twitch_message(data, conn=conn)\n            conn.commit()\n        return self.enqueue_decision(d, raw or data)\n\n    def enqueue_creator_message(self, text: str, event_type="voice") -> AttentionDecision:\n        return self.enqueue_decision(self.score_creator_event(text, event_type), {"text": text, "event_type": event_type})\n\n    def enqueue_vision_event(self, data: dict[str, Any], raw: dict[str, Any] | None = None) -> AttentionDecision:\n        return self.enqueue_decision(self.score_vision_event(data), raw or data)\n\n    def get_selected(self, limit=10, consume=False) -> list[dict[str, Any]]:\n        with self.connect() as conn:\n            rows = conn.execute("""SELECT * FROM attention_selected WHERE consumed=0\n                                   ORDER BY priority DESC, score DESC, created_ts ASC LIMIT ?""", (limit,)).fetchall()\n            items = [dict(r) for r in rows]\n            if consume and items:\n                ids = [i["event_id"] for i in items]\n                q = ",".join("?" for _ in ids)\n                conn.execute(f"UPDATE attention_selected SET consumed=1 WHERE event_id IN ({q})", ids)\n                conn.execute(f"UPDATE attention_events SET consumed=1 WHERE event_id IN ({q})", ids)\n                conn.commit()\n        return items\n\n    def build_digest(self, limit=8, consume=False) -> str:\n        items = self.get_selected(limit, consume)\n        if not items:\n            return ""\n        lines = ["### STREAM ATTENTION"]\n        for i in items:\n            reasons = ", ".join(json.loads(i.get("reasons_json") or "[]"))\n            who = i.get("user_name") or i.get("source") or "event"\n            text = normalize_text(i.get("text") or "")\n            if len(text) > 220:\n                text = text[:217].rstrip() + "..."\n            lines.append(f"- [{i[\'action\']}] score={i[\'score\']} prio={i[\'priority\']} from={who}: {text}" + (f" ({reasons})" if reasons else ""))\n        digest = "\\n".join(lines)\n        with self.connect() as conn:\n            conn.execute("INSERT INTO attention_digest_log(digest,event_count,created_ts,created_at) VALUES(?,?,?,?)",\n                         (digest, len(items), now_ts(), iso_now()))\n            conn.commit()\n        (LOGS / "monika_attention_digest.txt").write_text(digest, encoding="utf-8")\n        return digest\n\n    def summary(self) -> dict[str, Any]:\n        with self.connect() as conn:\n            total = conn.execute("SELECT COUNT(*) c FROM attention_events").fetchone()["c"]\n            selected = conn.execute("SELECT COUNT(*) c FROM attention_selected").fetchone()["c"]\n            pending = conn.execute("SELECT COUNT(*) c FROM attention_selected WHERE consumed=0").fetchone()["c"]\n            buckets = {r["bucket"]: r["c"] for r in conn.execute("SELECT bucket, COUNT(*) c FROM attention_events GROUP BY bucket")}\n            sources = {r["source"]: r["c"] for r in conn.execute("SELECT source, COUNT(*) c FROM attention_events GROUP BY source")}\n        return {"attention_events": total, "attention_selected": selected, "pending_selected": pending, "by_bucket": buckets, "by_source": sources}\n\n    @staticmethod\n    def _jsonl(path: Path, obj: dict[str, Any]) -> None:\n        path.parent.mkdir(parents=True, exist_ok=True)\n        with path.open("a", encoding="utf-8") as f:\n            f.write(json.dumps(obj, ensure_ascii=False) + "\\n")\n\ndef demo_selftest(db_path) -> dict[str, Any]:\n    layer = AttentionLayer(db_path)\n    d1 = layer.enqueue_twitch_message({"displayName":"viewer1","userId":"1","message":"лол"})\n    d2 = layer.enqueue_twitch_message({"displayName":"viewer2","userId":"2","message":"Моника, что думаешь про Dark Souls?"})\n    d3 = layer.enqueue_creator_message("Моника, проверь чат")\n    d4 = layer.enqueue_vision_event({"source":"obs","event_type":"SceneChanged","sceneName":"Dark Souls gameplay"})\n    assert d1.bucket == "ignored", d1\n    assert d2.bucket in ("selected","critical"), d2\n    assert d3.score == 1.0 and d3.priority == 100, d3\n    assert d4.bucket in ("background","selected"), d4\n    assert "STREAM ATTENTION" in layer.build_digest(limit=5)\n    return layer.summary()\n'
MODERATION_GOVERNOR = '\nfrom __future__ import annotations\nimport json, re, sqlite3, time, uuid\nfrom dataclasses import dataclass, asdict\nfrom pathlib import Path\nfrom typing import Any\nfrom attention_layer import resolve_db_path, normalize_text, text_lc, iso_now, now_ts\n\nROOT = Path(__file__).resolve().parent\nLOGS = ROOT / "Logs"\n\n@dataclass\nclass ModerationDecision:\n    action_id: str\n    platform: str\n    user_id: str\n    user_name: str\n    action: str\n    severity: int\n    reason: str\n    source_event_id: str\n    message: str\n    status: str\n    dry_run: int\n    created_ts: float\n    def to_dict(self) -> dict[str, Any]:\n        return asdict(self)\n\nclass ModerationGovernor:\n    def __init__(self, db_path=None, config: dict[str, Any] | None = None):\n        self.db_path = resolve_db_path(db_path)\n        self.config = config or {}\n        self.init_schema()\n\n    def connect(self):\n        conn = sqlite3.connect(str(self.db_path))\n        conn.row_factory = sqlite3.Row\n        return conn\n\n    def init_schema(self):\n        with self.connect() as conn:\n            conn.execute("""CREATE TABLE IF NOT EXISTS moderation_actions(\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                action_id TEXT UNIQUE, platform TEXT, user_id TEXT, user_name TEXT,\n                action TEXT, severity INTEGER, reason TEXT, source_event_id TEXT, message TEXT,\n                status TEXT, dry_run INTEGER, execute_payload_json TEXT,\n                created_ts REAL, created_at TEXT, executed_ts REAL, executed_at TEXT, error TEXT)""")\n            conn.execute("""CREATE TABLE IF NOT EXISTS moderation_user_state(\n                user_id TEXT PRIMARY KEY, user_name TEXT, last_message TEXT,\n                repeat_count INTEGER DEFAULT 0, warning_count INTEGER DEFAULT 0,\n                timeout_count INTEGER DEFAULT 0, last_seen_ts REAL, last_seen_at TEXT)""")\n            conn.commit()\n\n    def _update_user_state(self, user_id: str, user_name: str, normalized_text: str) -> int:\n        with self.connect() as conn:\n            row = conn.execute("SELECT last_message,repeat_count FROM moderation_user_state WHERE user_id=?", (user_id,)).fetchone()\n            if row is None:\n                repeat = 1\n                conn.execute("""INSERT INTO moderation_user_state(user_id,user_name,last_message,repeat_count,last_seen_ts,last_seen_at)\n                                VALUES(?,?,?,?,?,?)""", (user_id,user_name,normalized_text,repeat,now_ts(),iso_now()))\n            else:\n                repeat = int(row["repeat_count"] or 0) + 1 if str(row["last_message"] or "") == normalized_text else 1\n                conn.execute("""UPDATE moderation_user_state SET user_name=?,last_message=?,repeat_count=?,last_seen_ts=?,last_seen_at=?\n                                WHERE user_id=?""", (user_name,normalized_text,repeat,now_ts(),iso_now(),user_id))\n            conn.commit()\n        return repeat\n\n    def evaluate_twitch_message(self, event: dict[str, Any]) -> ModerationDecision | None:\n        text = normalize_text(event.get("text") or event.get("message") or "")\n        user_id = str(event.get("user_id") or event.get("userId") or event.get("user") or event.get("user_name") or "")\n        user_name = str(event.get("user_name") or event.get("displayName") or event.get("user") or user_id)\n        event_id = str(event.get("event_id") or event.get("message_id") or "")\n        if not text or not user_id:\n            return None\n        protected = {text_lc(x) for x in self.config.get("protected_users", [])}\n        if text_lc(user_id) in protected or text_lc(user_name) in protected:\n            return None\n        lc = text_lc(text)\n        repeat = self._update_user_state(user_id, user_name, lc)\n        banned_terms = [text_lc(x) for x in self.config.get("banned_terms", []) if str(x).strip()]\n        if any(term and term in lc for term in banned_terms):\n            return self.record_decision(user_id,user_name,"ban_candidate",90,"configured_banned_term",event_id,text)\n        if repeat >= 4:\n            return self.record_decision(user_id,user_name,"timeout_candidate",55,"repeat_spam",event_id,text)\n        if re.search(r"(.)\\1{12,}", text):\n            return self.record_decision(user_id,user_name,"warn_candidate",25,"char_spam",event_id,text)\n        if len(text) > 500:\n            return self.record_decision(user_id,user_name,"warn_candidate",20,"very_long_message",event_id,text)\n        return None\n\n    def record_decision(self, user_id, user_name, action, severity, reason, source_event_id, message) -> ModerationDecision:\n        dry = 1 if self.config.get("mode","dry_run") != "execute" else 0\n        status = "dry_run" if dry else "pending_execute"\n        d = ModerationDecision(f"mod_{uuid.uuid4().hex[:16]}", "twitch", user_id, user_name, action, int(severity), reason, source_event_id, message, status, dry, now_ts())\n        payload = self.build_streamerbot_payload(d)\n        with self.connect() as conn:\n            conn.execute("""INSERT OR IGNORE INTO moderation_actions(\n                action_id,platform,user_id,user_name,action,severity,reason,source_event_id,message,status,dry_run,execute_payload_json,created_ts,created_at)\n                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",\n                (d.action_id,d.platform,d.user_id,d.user_name,d.action,d.severity,d.reason,d.source_event_id,d.message,d.status,d.dry_run,json.dumps(payload,ensure_ascii=False),d.created_ts,iso_now()))\n            conn.commit()\n        self._jsonl(LOGS / "moderation_actions.jsonl", d.to_dict() | {"execute_payload": payload})\n        return d\n\n    def build_streamerbot_payload(self, d: ModerationDecision) -> dict[str, Any]:\n        names = self.config.get("streamerbot_action_names", {}) or {}\n        action_name = names.get(d.action, "")\n        return {\n            "request": "DoAction",\n            "id": d.action_id,\n            "action": {"name": action_name} if action_name else {},\n            "args": {\n                "platform": d.platform, "userId": d.user_id, "userName": d.user_name,\n                "reason": d.reason, "severity": d.severity, "sourceEventId": d.source_event_id,\n                "message": d.message, "monikaDryRun": bool(d.dry_run)\n            }\n        }\n\n    def pending_for_execution(self, limit=10) -> list[dict[str, Any]]:\n        with self.connect() as conn:\n            rows = conn.execute("""SELECT * FROM moderation_actions WHERE status=\'pending_execute\' AND dry_run=0\n                                   ORDER BY severity DESC, created_ts ASC LIMIT ?""", (limit,)).fetchall()\n        return [dict(r) for r in rows]\n\n    def mark_executed(self, action_id: str, status="executed", error=""):\n        with self.connect() as conn:\n            conn.execute("UPDATE moderation_actions SET status=?,error=?,executed_ts=?,executed_at=? WHERE action_id=?",\n                         (status,error,now_ts(),iso_now(),action_id))\n            conn.commit()\n\n    def summary(self) -> dict[str, Any]:\n        with self.connect() as conn:\n            total = conn.execute("SELECT COUNT(*) c FROM moderation_actions").fetchone()["c"]\n            by_status = {r["status"]: r["c"] for r in conn.execute("SELECT status,COUNT(*) c FROM moderation_actions GROUP BY status")}\n            by_action = {r["action"]: r["c"] for r in conn.execute("SELECT action,COUNT(*) c FROM moderation_actions GROUP BY action")}\n        return {"moderation_actions": total, "by_status": by_status, "by_action": by_action}\n\n    @staticmethod\n    def _jsonl(path: Path, obj: dict[str, Any]):\n        path.parent.mkdir(parents=True, exist_ok=True)\n        with path.open("a", encoding="utf-8") as f:\n            f.write(json.dumps(obj, ensure_ascii=False) + "\\n")\n\ndef demo_selftest(db_path) -> dict[str, Any]:\n    gov = ModerationGovernor(db_path, {"mode":"dry_run", "banned_terms":["__forbidden_test_term__"]})\n    assert gov.evaluate_twitch_message({"user_id":"u1","user_name":"viewer","text":"hello"}) is None\n    for _ in range(3):\n        gov.evaluate_twitch_message({"user_id":"u2","user_name":"spammer","text":"spam"})\n    d4 = gov.evaluate_twitch_message({"user_id":"u2","user_name":"spammer","text":"spam"})\n    assert d4 and d4.action == "timeout_candidate" and d4.dry_run == 1, d4\n    d5 = gov.evaluate_twitch_message({"user_id":"u3","user_name":"bad","text":"__forbidden_test_term__"})\n    assert d5 and d5.action == "ban_candidate" and d5.dry_run == 1, d5\n    return gov.summary()\n'
STREAMERBOT_BRIDGE = '\nfrom __future__ import annotations\nimport argparse, asyncio, json, time\nfrom pathlib import Path\nfrom typing import Any\nfrom attention_layer import AttentionLayer, normalize_text\nfrom moderation_governor import ModerationGovernor\n\nROOT = Path(__file__).resolve().parent\nLOGS = ROOT / "Logs"\nCONFIG_PATH = ROOT / "streamerbot_attention_config.json"\n\nDEFAULT_CONFIG = {\n  "streamerbot_ws": {\n    "host": "127.0.0.1", "port": 8080, "endpoint": "/", "password": "",\n    "subscribe": {\n      "Twitch": ["ChatMessage","Follow","Cheer","Sub","ReSub","GiftSub","GiftBomb","Raid","RewardRedemption","StreamUpdate","UserTimedOut","UserBanned"],\n      "Obs": ["Connected","Disconnected","SceneChanged","StreamingStarted","StreamingStopped","RecordingStarted","RecordingStopped","Event"]\n    }\n  },\n  "attention": {"consume_after_digest": False, "digest_limit": 8},\n  "moderation": {\n    "mode": "dry_run",\n    "protected_users": ["Duncan"],\n    "banned_terms": [],\n    "streamerbot_action_names": {\n      "warn_candidate": "", "timeout_candidate": "", "ban_candidate": "",\n      "vip_candidate": "", "unvip_candidate": "", "unban_candidate": ""\n    }\n  }\n}\n\ndef load_config() -> dict[str, Any]:\n    if not CONFIG_PATH.exists():\n        CONFIG_PATH.write_text(json.dumps(DEFAULT_CONFIG, ensure_ascii=False, indent=2), encoding="utf-8")\n        print(f"[config] created {CONFIG_PATH.name}")\n    data = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))\n    cfg = json.loads(json.dumps(DEFAULT_CONFIG))\n    for k, v in data.items():\n        if isinstance(v, dict) and isinstance(cfg.get(k), dict):\n            cfg[k].update(v)\n        else:\n            cfg[k] = v\n    return cfg\n\ndef append_jsonl(path: Path, obj: dict[str, Any]):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    with path.open("a", encoding="utf-8") as f:\n        f.write(json.dumps(obj, ensure_ascii=False) + "\\n")\n\ndef normalize_twitch_chat(raw: dict[str, Any]) -> dict[str, Any]:\n    data = raw.get("data") or {}\n    event = raw.get("event") or {}\n    user_obj = data.get("user") if isinstance(data.get("user"), dict) else {}\n    msg_obj = data.get("message") if isinstance(data.get("message"), dict) else {}\n    text = data.get("message") if isinstance(data.get("message"), str) else msg_obj.get("message") or msg_obj.get("text") or data.get("text") or data.get("rawInput") or data.get("input") or ""\n    user_name = data.get("displayName") or data.get("userName") or data.get("username") or data.get("login") or user_obj.get("display") or user_obj.get("name") or user_obj.get("login") or ""\n    user_id = data.get("userId") or data.get("user_id") or user_obj.get("id") or user_name or ""\n    return {"event_id": str(data.get("messageId") or data.get("id") or raw.get("id") or ""),\n            "event_type": event.get("type", "ChatMessage"),\n            "user_id": str(user_id), "user_name": str(user_name), "displayName": str(user_name),\n            "message": normalize_text(str(text)), "raw": raw}\n\ndef normalize_obs(raw: dict[str, Any]) -> dict[str, Any]:\n    event = raw.get("event") or {}\n    data = raw.get("data") or {}\n    typ = str(event.get("type") or data.get("event") or data.get("obsEvent.event") or "ObsEvent")\n    scene = data.get("sceneName") or data.get("obs.sceneName") or data.get("obsSceneName") or data.get("newSceneName") or data.get("obsEvent.sceneName") or ""\n    old = data.get("oldSceneName") or data.get("obs.oldSceneName") or ""\n    text = " | ".join([x for x in [f"OBS {typ}", f"{old} -> {scene}" if old and scene else str(scene or "")] if x])\n    return {"source":"obs", "event_type": typ, "text": text, "sceneName": scene, "oldSceneName": old, "raw": raw}\n\nasync def send_json(ws, obj):\n    await ws.send(json.dumps(obj, ensure_ascii=False))\n\nasync def execute_action(ws, payload: dict[str, Any]) -> bool:\n    if not payload.get("action"):\n        return False\n    await send_json(ws, payload)\n    return True\n\nasync def run_bridge(cfg: dict[str, Any]):\n    try:\n        import websockets  # type: ignore\n    except ImportError:\n        raise SystemExit("Missing dependency: websockets. Run: python -m pip install websockets")\n    ws_cfg = cfg["streamerbot_ws"]\n    url = f"ws://{ws_cfg.get(\'host\',\'127.0.0.1\')}:{int(ws_cfg.get(\'port\',8080))}{ws_cfg.get(\'endpoint\',\'/\')}"\n    print(f"[connect] {url}")\n    attention = AttentionLayer()\n    moderation = ModerationGovernor(config=cfg.get("moderation", {}))\n    async with websockets.connect(url, ping_interval=20, ping_timeout=20) as ws:\n        await send_json(ws, {"request":"GetInfo","id":"monika-get-info"})\n        await send_json(ws, {"request":"Subscribe","id":"monika-attention-subscribe","events": ws_cfg.get("subscribe")})\n        print("[subscribe]", json.dumps(ws_cfg.get("subscribe"), ensure_ascii=False))\n        print("[mode] moderation:", cfg.get("moderation",{}).get("mode","dry_run"))\n        while True:\n            msg = await ws.recv()\n            try:\n                raw = json.loads(msg)\n            except json.JSONDecodeError:\n                append_jsonl(LOGS/"streamerbot_raw_nonjson.log", {"ts":time.time(), "message":msg})\n                continue\n            append_jsonl(LOGS/"streamerbot_raw_events.jsonl", raw)\n            ev = raw.get("event") or {}\n            source = str(ev.get("source") or "")\n            typ = str(ev.get("type") or "")\n            if raw.get("id") in {"monika-get-info","monika-attention-subscribe"}:\n                print("[server]", json.dumps(raw, ensure_ascii=False)[:500])\n                continue\n            if source.casefold() == "twitch" and typ == "ChatMessage":\n                data = normalize_twitch_chat(raw)\n                d = attention.enqueue_twitch_message(data, raw)\n                m = moderation.evaluate_twitch_message({"event_id":d.event_id,"user_id":d.user_id,"user_name":d.user_name,"text":d.text})\n                print(f"[chat:{d.bucket}] {d.user_name}: {d.text} score={d.score} action={d.action}")\n                if m:\n                    print(f"[mod:{m.status}] {m.user_name} {m.action} reason={m.reason}")\n                    if m.dry_run == 0:\n                        for row in moderation.pending_for_execution(limit=3):\n                            payload = json.loads(row.get("execute_payload_json") or "{}")\n                            try:\n                                ok = await execute_action(ws, payload)\n                                moderation.mark_executed(row["action_id"], "executed" if ok else "skipped_no_action")\n                            except Exception as e:\n                                moderation.mark_executed(row["action_id"], "error", str(e))\n            elif source.casefold() == "obs":\n                data = normalize_obs(raw)\n                d = attention.enqueue_vision_event(data, raw)\n                print(f"[obs:{d.bucket}] {d.text} score={d.score}")\n            else:\n                if source or typ:\n                    print(f"[event] {source}.{typ}")\n\ndef inject_creator(text: str):\n    d = AttentionLayer().enqueue_creator_message(text)\n    print(json.dumps(d.to_dict(), ensure_ascii=False, indent=2))\n\ndef print_digest(consume=False):\n    cfg = load_config()\n    limit = int(cfg.get("attention",{}).get("digest_limit", 8))\n    digest = AttentionLayer().build_digest(limit=limit, consume=consume)\n    print(digest or "<empty>")\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--inject-creator")\n    ap.add_argument("--digest", action="store_true")\n    ap.add_argument("--consume", action="store_true")\n    args = ap.parse_args()\n    if args.inject_creator:\n        inject_creator(args.inject_creator); return\n    if args.digest:\n        print_digest(args.consume); return\n    try:\n        asyncio.run(run_bridge(load_config()))\n    except KeyboardInterrupt:\n        print("\\\\n[stop]")\n\nif __name__ == "__main__":\n    main()\n'
INSPECT_ATTENTION = '\nfrom __future__ import annotations\nimport json\nfrom attention_layer import AttentionLayer\n\ndef main():\n    layer = AttentionLayer()\n    print("Attention summary:")\n    print(layer.summary())\n    print()\n    print("Pending selected events:")\n    items = layer.get_selected(limit=20, consume=False)\n    if not items:\n        print("  <empty>")\n    for i in items:\n        reasons = ", ".join(json.loads(i.get("reasons_json") or "[]"))\n        print(f"- [{i[\'action\']}] score={i[\'score\']} prio={i[\'priority\']} {i[\'source\']}/{i[\'event_type\']} {i.get(\'user_name\') or \'\'}: {i.get(\'text\') or \'\'}" + (f" ({reasons})" if reasons else ""))\n    print()\n    print("Current digest:")\n    print(layer.build_digest(limit=8, consume=False) or "  <empty>")\n\nif __name__ == "__main__":\n    main()\n'
INSPECT_MODERATION = '\nfrom __future__ import annotations\nfrom moderation_governor import ModerationGovernor\n\ndef main():\n    gov = ModerationGovernor()\n    print("Moderation summary:")\n    print(gov.summary())\n    print()\n    with gov.connect() as conn:\n        rows = conn.execute("SELECT * FROM moderation_actions ORDER BY created_ts DESC LIMIT 20").fetchall()\n    print("Recent moderation actions:")\n    if not rows:\n        print("  <empty>")\n    for r in rows:\n        print(f"- [{r[\'status\']}] {r[\'action\']} severity={r[\'severity\']} user={r[\'user_name\']} reason={r[\'reason\']} dry_run={r[\'dry_run\']}")\n        if r["message"]:\n            print("  msg:", str(r["message"])[:180])\n\nif __name__ == "__main__":\n    main()\n'
README = '\n# Monika Streamer.bot Attention Stack v1\n\nSafe by default:\n- Reads Twitch chat from Streamer.bot WebSocket.\n- Reads OBS events from Streamer.bot WebSocket.\n- Scores events before Monika sees them.\n- Records moderation candidates in dry-run mode.\n- Does not write to Twitch.\n- Does not ban/timeout/VIP anyone.\n- Does not patch console_chat.py.\n\nRun:\n  python -m pip install websockets\n  python streamerbot_attention_bridge.py\n\nInspect:\n  python inspect_attention.py\n  python inspect_moderation.py\n  python streamerbot_attention_bridge.py --digest\n\nTest creator event:\n  python streamerbot_attention_bridge.py --inject-creator "Моника, проверь чат"\n\nReal moderation requires:\n- manually configured Streamer.bot actions,\n- action names in streamerbot_attention_config.json,\n- moderation.mode = "execute".\nKeep dry_run until several real tests pass.\n'
CONFIG = {'streamerbot_ws': {'host': '127.0.0.1', 'port': 8080, 'endpoint': '/', 'password': '', 'subscribe': {'Twitch': ['ChatMessage', 'Follow', 'Cheer', 'Sub', 'ReSub', 'GiftSub', 'GiftBomb', 'Raid', 'RewardRedemption', 'StreamUpdate', 'UserTimedOut', 'UserBanned'], 'Obs': ['Connected', 'Disconnected', 'SceneChanged', 'StreamingStarted', 'StreamingStopped', 'RecordingStarted', 'RecordingStopped', 'Event']}}, 'attention': {'consume_after_digest': False, 'digest_limit': 8}, 'moderation': {'mode': 'dry_run', 'protected_users': ['Duncan'], 'banned_terms': [], 'streamerbot_action_names': {'warn_candidate': '', 'timeout_candidate': '', 'ban_candidate': '', 'vip_candidate': '', 'unvip_candidate': '', 'unban_candidate': ''}}}

FILES = {
    "attention_layer.py": ATTENTION_LAYER,
    "moderation_governor.py": MODERATION_GOVERNOR,
    "streamerbot_attention_bridge.py": STREAMERBOT_BRIDGE,
    "inspect_attention.py": INSPECT_ATTENTION,
    "inspect_moderation.py": INSPECT_MODERATION,
    "README_streamerbot_attention_stack.md": README,
    "streamerbot_attention_config.example.json": json.dumps(CONFIG, ensure_ascii=False, indent=2) + "\n",
}

def backup(path: Path, backups):
    if path.exists():
        bak = path.with_name(path.name + ".bak_" + TAG)
        shutil.copy2(path, bak)
        backups.append((path, bak))
        print(f"[backup] {path.name} -> {bak.name}")

def rollback(backups, created):
    print("[rollback] restoring backups...")
    for path, bak in reversed(backups):
        if bak.exists():
            shutil.copy2(bak, path)
            print(f"[rollback] {bak.name} -> {path.name}")
    for path in created:
        if path.exists() and not any(path == p for p, _ in backups):
            path.unlink()
            print(f"[rollback] removed created {path.name}")

def write_files(backups, created):
    for name, content in FILES.items():
        path = ROOT / name
        if path.exists():
            backup(path, backups)
        else:
            created.append(path)
        path.write_text(content.lstrip("\n"), encoding="utf-8")
        print(f"[written] {name}")
    cfg = ROOT / "streamerbot_attention_config.json"
    if not cfg.exists():
        cfg.write_text(json.dumps(CONFIG, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        created.append(cfg)
        print("[written] streamerbot_attention_config.json")
    else:
        print("[keep] streamerbot_attention_config.json already exists")

def run_checks():
    print("[check] py_compile...")
    for name in FILES:
        if name.endswith(".py"):
            py_compile.compile(str(ROOT / name), doraise=True)
    print("[check] ast parse...")
    for name in FILES:
        if name.endswith(".py"):
            ast.parse((ROOT / name).read_text(encoding="utf-8"))
    print("[check] self-test attention/moderation...")
    with tempfile.TemporaryDirectory() as td:
        db = Path(td) / "test.db"
        sys.path.insert(0, str(ROOT))
        try:
            import importlib
            if "attention_layer" in sys.modules:
                del sys.modules["attention_layer"]
            if "moderation_governor" in sys.modules:
                del sys.modules["moderation_governor"]
            attention_layer = importlib.import_module("attention_layer")
            moderation_governor = importlib.import_module("moderation_governor")
            att = attention_layer.demo_selftest(db)
            mod = moderation_governor.demo_selftest(db)
            assert att["attention_events"] >= 4, att
            assert att["attention_selected"] >= 2, att
            assert mod["moderation_actions"] >= 2, mod
            assert "dry_run" in mod["by_status"], mod
        finally:
            if str(ROOT) in sys.path:
                sys.path.remove(str(ROOT))
    print("[ok] self-test passed")

def main():
    backups, created = [], []
    try:
        write_files(backups, created)
        run_checks()
    except Exception as e:
        print(f"[ERROR] {e}")
        rollback(backups, created)
        raise
    print("[ok] Streamer.bot Attention Stack v1 applied.")
    print("Next:")
    print("  python -m pip install websockets")
    print("  python inspect_attention.py")
    print("  python inspect_moderation.py")
    print("  python streamerbot_attention_bridge.py")

if __name__ == "__main__":
    main()
